+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\hwdesk\Service;
+
+use Drupal\Component\Datetime\TimeInterface;
+use Drupal\Core\State\StateInterface;
+
+/**
+ * Service for generating protocol numbers.
+ */
+final class ProtocolNumbers {
+  public function __construct(
+    private readonly StateInterface $state,
+    private readonly TimeInterface $time
+  ) {}
+
+  /**
+   * Returns the next protocol number and stores it.
+   */
+  public function next(): string {
+    $year = (string) date('Y', $this->time->getRequestTime());
+    $key = 'hwdesk.protocol_seq.' . $year;
+    $current = $this->state->get($key);
+    if (!is_int($current)) {
+      $current = 0;
+    }
+    $next = $current + 1;
+    $this->state->set($key, $next);
+    return $this->format($year, $next);
+  }
+
+  /**
+   * Returns the protocol number that would be returned by next(), without storing it.
+   */
+  public function peek(): string {
+    $year = (string) date('Y', $this->time->getRequestTime());
+    $key = 'hwdesk.protocol_seq.' . $year;
+    $current = $this->state->get($key);
+    if (!is_int($current)) {
+      $current = 0;
+    }
+    return $this->format($year, $current + 1);
+  }
+
+  private function format(string $year, int $seq): string {
+    $padded = str_pad((string) $seq, 4, '0', STR_PAD_LEFT);
+    return "HP-{$year}-{$padded}";
+  }
+}
